// Paper-trace: worst-case vertical GoalNear(range) vs 4.2 eye-to-center law
function worstVertical(range, eyeHeight, blockCenterOffset) {
  // node.y = by + range (dy budget fully spent on y), bot.y in [node.y, node.y+1)
  // worst continuous bot.y = node.y + 0.999
  const botYOffsetFromBlockY = range + 0.999; // bot.y - by
  const eyeY = botYOffsetFromBlockY + eyeHeight; // eye - by
  const vert = eyeY - blockCenterOffset; // eye - (by+0.5)
  return vert;
}
for (const range of [2, 1]) {
  const vert = worstVertical(range, 1.62, 0.5);
  console.log(`range=${range}: worst-case vertical eye-to-center = ${vert.toFixed(3)}`);
  // add worst horizontal slop (~1 block possible at same range budget if axis independent, but with dy alone using full budget dx=dz=0 so horiz slop bounded by sub-cell only ~0.5-0.71 typically)
  for (const horiz of [0, 0.5, 0.71, 1.0]) {
    const total = Math.hypot(vert, horiz);
    console.log(`  + horiz ${horiz.toFixed(2)} => total ${total.toFixed(3)} ${total > 4.2 ? '(EXCEEDS 4.2)' : '(within 4.2)'}`);
  }
}

// GoalGetToBlock legacy bug reconstruction: range=0 threshold vs real "adjacent" 1-cell requirement
console.log('\nGoalGetToBlock legacy bug: cell(1.0) + center(0.5) + body-radius(0.3) =', (1.0+0.5+0.3).toFixed(2));
EOF
